def get_axioms() -> list:
    # VALUE fix (added unnegated as a precondition): alpha (Scalar) taking nan/inf
    # overflows on conversion to an *integral* result dtype ("value cannot be
    # converted to type intN_t without overflow"). The result is integral iff
    # neither self nor other is floating (Half=5,Float=6,Double=7,BF16=15) or
    # complex (CHalf=8,CFloat=9,CDouble=10). Require alpha finite unless at least
    # one operand is floating/complex (then nan/inf is a valid value).
    _self_fp = Or(Int('self.dtype') == IntVal(5), Int('self.dtype') == IntVal(6),
                  Int('self.dtype') == IntVal(7), Int('self.dtype') == IntVal(15),
                  Int('self.dtype') == IntVal(8), Int('self.dtype') == IntVal(9),
                  Int('self.dtype') == IntVal(10))
    _other_fp = Or(Int('other.dtype') == IntVal(5), Int('other.dtype') == IntVal(6),
                   Int('other.dtype') == IntVal(7), Int('other.dtype') == IntVal(15),
                   Int('other.dtype') == IntVal(8), Int('other.dtype') == IntVal(9),
                   Int('other.dtype') == IntVal(10))
    return [
        Implies(Or(Bool('alpha.is_nan'), Bool('alpha.is_inf')),
                Or(_self_fp, _other_fp)),
    ]


def get_vars() -> dict:
    pass
    return {}


def build_solver() -> Solver:
    s = Solver()
    s.add(*get_axioms())
    return s
